function UIActionDungoenCollectionDialog:Awake()
    -- init data
    ---@type RegionEntryVo[]
    local tempData = CfUtils.GetCf(AutoIds.IdSetting3042, "RegionEntryVo", true)
    SortByMember(tempData, "position")

    -- add listens
