function UIActionDungoenCollectionDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams = CfUtils.DialogSafeParameters(self.controller)
        self.gridViewOffsetX_ = initParams.gridViewOffsetX

        local dialog = CfUtils.DialogGet(Constants.UITypeIds.UIActionPrimaryMapDialog)
        if isNotNull(dialog) then
            dialog.CacheCanvas.enabled = false
        end
    end)
end


function UIActionDungoenCollectionDialog:OnFinalize()
    return CoWaitDo(function()
        local initParams = self.controller.Argument.parameters or {}

        -- save last gridViewOffX
        local entryGridContent = self.ScrollView.transform:Find('Viewport/Content')
        initParams.gridViewOffsetX = entryGridContent.anchoredPosition.x

        local dialog = CfUtils.DialogGet(Constants.UITypeIds.UIActionPrimaryMapDialog)
        if isNotNull(dialog) then
            dialog.CacheCanvas.enabled = true
        end

        for _, redPointKeyword in pairs(EntryRedPointMap) do
            GameUtils.RemoveRedPointCallBack(redPointKeyword)
        end
        GameUtils.RemoveRedPointCallBack(Constants.RedPointConst.PhoneFishCollection)

        self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象
        self:Delete()
    end)
end


function UIActionDungoenCollectionDialog:OnShow()
    return CoWaitDo(function()
        local isFromMainMap = checkInt(CfUtils.CookieLoad("UIActionDungoenCollectionDialogEntry")) == 1
        if isFromMainMap then
            CfUtils.PlayAnimation(self.Root, ROOT_ANIM_NAME.SHOW)
            -- 入场动画播放0.23s后，再出现列表
            CoYield(0.25)
            self:UpdateRegionEntryList_()
        else
            CfUtils.PlayAnimation(self.Root, ROOT_ANIM_NAME.IDLE)
            self:UpdateRegionEntryList_()
        end
        CfUtils.CookieSave("UIActionDungoenCollectionDialogEntry", 0)
    end)
end


