-- private

function UIActionDungoenCollectionDialog:UpdateRegionEntryList_()
    -- check recover offsetX
    if self.gridViewOffsetX_ then
        -- 防止要做动画
        self.ScrollView.DisplayItemNumber = self.ScrollView.DisplayItemCount
        CfUtils.WaitCallbackSafeTo(function()
            CoYield()  -- 需要等待1帧，让reload列表内容计算生效，才能正确移动到目标为止
            self.ScrollView:MovePanelToItemByIndex(0, self.gridViewOffsetX_ + self.ScrollView.Padding.left)
            self.gridViewOffsetX_ = nil

        end)
    else
        -- 重新计数动画
        self.ScrollView.DisplayItemNumber = 0
    end

    -- reload gridView
    local entryDataLength = #self:GetRegionEntryDataList()
    GameUtils.ReloadData(self.ScrollView, entryDataLength)

    -- 如果这里不重置一下的话，保持原地位置反复进出界面，会发现这个列表一直累计偏移值，导致越来越越偏
    self.ScrollView.ContainerTrans.anchoredPosition3D = Vector3(0,0,0)
    self.ScrollView:VaildAndSetContainerPos()
end


