---@param gridView SuperScrollView.LoopGridView
---@param luaIndex integer @ start at 1
---@return SuperScrollView.LoopGridViewItem
function UIActionDungoenCollectionDialog:OnUpdateRegionEntryGridViewHandler_(gridView, luaIndex)
    local cellNode = gridView:NewListViewItem(EntryCellNodeName)
    local cellData = checkTable(self:GetRegionEntryDataList()[luaIndex])
    ---@type UIActionDungoenCollectionNode
    local cellEnv = CfUtils.GetLuaScr(cellNode, EntryCellNodePath)
    if isNotNull(cellEnv) then
        -- init cell
        cellEnv:SetLuaIndex(luaIndex)
        cellEnv:SetCellData({
            regionEntryVo = cellData,
            idRedPointMap = EntryRedPointMap
        })
        cellEnv:SetClickCellCB(Bind(self, self.OnClickDungoenCollectionCellHandler_))
        -- play anim
        if gridView.DisplayItemNumber < gridView.DisplayItemCount then
            cellEnv:PlayDelayAnimByShow(gridView.DisplayItemNumber)
            gridView.DisplayItemNumber = gridView.DisplayItemNumber + 1
        else
            cellEnv:PlayAnimByIdle()
        end
    end
    return cellNode
end


---@param luaIndex integer @ start at 1
---@param sender UIActionDungoenCollectionNode
function UIActionDungoenCollectionDialog:OnClickDungoenCollectionCellHandler_(luaIndex, sender)
    local cellData = sender:GetCellData()
    
    ---@type RegionEntryVo
    local regionEntryVo = checkTable(cellData.regionEntryVo)
    local regionEntryId = checkInt(regionEntryVo.uid)

    -- check unlcok
    local isUnlock, _ = GameUtils.IsUnlockedSingle(regionEntryVo.unlockType, regionEntryVo.unlockNum, regionEntryVo.unlockId)
    if not isUnlock then
        GameUtils.Toast(GameUtils.GetUnlockDescr(regionEntryVo.unlockType, regionEntryVo.unlockNum, regionEntryVo.unlockId))
        return
    end

    -- FIXME 为啥没有添加 DIALOG_BLOCK_NAME 的逻辑呢？
    xTry(function()
        CfUtils.ConditionRemove(DIALOG_BLOCK_NAME)
        CoStart(function()
            local exclusiveIds = CfUtils.DialogGetAllArgs()

            -- BOSS战
            if regionEntryId == Constants.SystemToggleIds.Id2006 then
                xRecord.record('2-007')
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionBossCollectionDialog, {}, exclusiveIds))

            -- 装备本总览
            elseif regionEntryId == Constants.SystemToggleIds.Id2004 then
                xRecord.record('2-004')
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionEquipCollectionDialog, {}, exclusiveIds))

            -- 日常本（经验本、芯片本、粒子本）| 歼灭战斗（协力战）
            elseif regionEntryId == Constants.SystemToggleIds.Id3 or regionEntryId == Constants.SystemToggleIds.Id2003 then
                xRecord.record('2-005')
                local areaPointId = checkInt(regionEntryVo.areaPointId)
                if areaPointId <= 0 then
                    return
                end
                KCookie.Set("UIActionSecondMapDialogtargetPointId", areaPointId)

                local isInSecondMap = false
                for _, exclusiveUIArgs in ipairs(exclusiveIds) do
                     if exclusiveUIArgs.id == Constants.UITypeIds.UIActionSecondMapDialog then
                        isInSecondMap = true
                        break
                     end
                end

                if isInSecondMap then
                    Events.Broadcast(Constants.EventNames.ActionSecondMapJump, nil)
                else
                    local ActionUtils    = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
                    local secondaryMapVo = ActionUtils.GetRegionSecondaryMapVo(areaPointId)
                    local secondMapArgs  = {id = checkInt(secondaryMapVo.regionBelong), targetPointId = areaPointId, isFromEntry = true}
                    CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIActionSecondMapDialog, secondMapArgs, exclusiveIds))
                end

            -- 世界BOSS
            elseif regionEntryId == Constants.SystemToggleIds.Id14 then
                xRecord.record('2-008')
                ---@type WorldBossComponent
                local worldBossComponent = GameUtils.GetOrAddEntityCompByType(ECSComponentType.Constants.WorldBossComponent)
                worldBossComponent:OnWorldBossEnter()

            -- 异步PVP（幻境斗技场）
            elseif regionEntryId == Constants.SystemToggleIds.Id2007 then
                xRecord.record('2-006')
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderStruggleMainDialog, {systemName = Constants.SystemToggleIds.Id2007}, exclusiveIds))

            -- 实时PVP（天梯竞技场）
            elseif regionEntryId == Constants.SystemToggleIds.Id2008 then
                xRecord.record('2-009')
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderCompetionMainDialog, nil, exclusiveIds))

            -- 幻影特训场
            elseif regionEntryId == Constants.SystemToggleIds.Id2017 then
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.LadderStruggleSingleMainDialog, {systemName = Constants.SystemToggleIds.Id2017}, exclusiveIds))

            -- 钓鱼
            elseif regionEntryId == Constants.SystemToggleIds.Id233 then  
                CoYield(CfUtils.DialogOpen(Constants.UITypeIds.UIFishPoolMainDialog, nil, exclusiveIds))

            end
        end)
    end, function()
        print(debug.traceback())
        CfUtils.ConditionRemove(DIALOG_BLOCK_NAME)
    end)
end


return UIActionDungoenCollectionDialog
